            return; // email is optional
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (DuplicateMatching.sameValue(email, existing.getEmail())) {
                throw new DuplicateOwnerException("An owner with the same email already exists");
            }
        }
    }
